import React, { useState, useContext, useCallback } from "react";

import styles from "./contact.module.css";

import Footer from "../../components/Footer/Footer.js";
import { CursorContext } from "../../components/Cursor/CursorContextProvider";

const ContactPage = () => {
  const [showSub, setShowSub] = useState(false);
  const [, setCursor] = useContext(CursorContext);

  const toggleSubscribe = () => {
    setShowSub((prevShowSub) => !prevShowSub);
  };

  const toggleCursor = useCallback(() => {
    setCursor(({ active }) => ({ active: !active }));
  });

  return (
    <>
      <div className={styles["outer"]}>
        <div className={styles["contactPage"]}>
          <div className={styles["container"]}>
            <div className={styles["column"]}>
              <div className={styles["row-col"]}>
              <span className={styles["rotation"]}>PHYSICAL</span>
              <span className={styles["details"]}>
              <div>

              <p style={{ margin: 0, display: "flex", alignItems: "baseline" }}>
                <span style={{ fontFamily: "inherit", fontWeight: "inherit" }}>
                  Visit:
                </span>
                <a
                  href="https://www.google.com/maps/place/101-103+Brunswick+Street,+Fitzroy,+VIC,+3065,+Australia"
                  target="_blank"
                  className={styles["details"]}
                  style={{
                    marginLeft: "6px",
                    textDecoration: "underline",
                    color: "inherit",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={toggleCursor}
                  onMouseLeave={toggleCursor}
                >
                  101-103 Brunswick Street, Fitzroy, VIC, 3065, Australia
                </a>
              </p>

<br/>
              <a
              href="https://maps.app.goo.gl/GQpJBwf5WHvjkk5u6"
              target="_blank"
              onMouseEnter={toggleCursor}
              onMouseLeave={toggleCursor}
              >
              Visit: 101-103 Brunswick Street, Fitzroy, VIC, 3065, Australia
              </a>
              <br /><br />

              <a
              href="#"
              onMouseEnter={toggleCursor}
              onMouseLeave={toggleCursor}
              style={{ pointerEvents: "none", textDecoration: "none" }}
              >
              Mail: P.O Box 4196, Fitzroy, VIC, 3065, Australia
              </a>
              <br /><br />

              <p style={{ margin: 0 }}>
  <span>Telephone:</span>{" "}
  <a
    href="tel:+61399697111"
    className={styles["details"]}
    style={{
      color: "inherit",
      textDecoration: "none",
      marginLeft: "0px",
      display: "inline-block",
      fontFamily: "inherit",
    }}
    onMouseEnter={toggleCursor}
    onMouseLeave={toggleCursor}
  >
  (03) 9969 7111
  </a>
</p>

              <br />

              <a
              href="#"
              onMouseEnter={toggleCursor}
              onMouseLeave={toggleCursor}
              style={{ pointerEvents: "none", textDecoration: "none" }}
              >
              We are currently only open by appointment and for events.
              </a>
  </div>
</span>
</div>

<div className={styles["column"]}>

                <span className={styles["rotation"]}>DIGITAL</span>

                <span className={styles["links"]}>
                  <div>
                    <a
                      href="https://www.instagram.com/terrain.earth/"
                      target="_blank"
                      onMouseEnter={toggleCursor}
                      onMouseLeave={toggleCursor}
                    >
                      INSTAGRAM
                    </a>
                  </div>
                  <div>
                    <a
                      href="https://www.are.na/terrain"
                      target="_blank"
                      onMouseEnter={toggleCursor}
                      onMouseLeave={toggleCursor}
                    >
                      ARE.NA
                    </a>
                  </div>
                  <div>
                    <a
                      href="https://open.spotify.com/user/1232587233?si=00d0fc16457843a0"
                      target="_blank"
                      onMouseEnter={toggleCursor}
                      onMouseLeave={toggleCursor}
                    >
                      SPOTIFY
                    </a>
                  </div>
                </span>
              </div>
            </div>
          </div>
          <div className={styles["container-2"]}>
            <div className={styles["column"]}>
              <div className={styles["textbox"]}>
                <p>
                  General enquiries: hello@TERRAIN.earth
                  <br></br>
                  Book related enquiries: books@TERRAIN.earth
                  <br></br>
                  <br></br>
                  <a
                    href="/privacypolicy"
                    onMouseEnter={toggleCursor}
                    onMouseLeave={toggleCursor}
                  >
                    Privacy Policy
                  </a>{" "}
                  and{" "}
                  <a
                    href="/termsconditions"
                    onMouseEnter={toggleCursor}
                    onMouseLeave={toggleCursor}
                  >
                    Terms and Conditions
                  </a>
                  .<br></br>
                  <br></br>
                  This is a renewably-powered self-hosted website.
                  <br></br>
                  <br></br>
                  <a
                    className={styles["menuBtn"]}
                    onClick={() => toggleSubscribe() && setCursor(true)}
                    onMouseEnter={toggleCursor}
                    onMouseLeave={toggleCursor}
                  >
                    Subscribe
                  </a>{" "}
                  {showSub ? (
                    <>
                      <div
                        id="subscribe"
                        className={styles["sub-wrap"]}
                        onClick={() => setShowSub(false) && setCursor()}
                        onMouseEnter={toggleCursor}
                        onMouseLeave={toggleCursor}
                      ></div>
                      <div className={styles["sub-inner"]}>
                        <div class="klaviyo-form-WdFuEM"></div>
                      </div>
                    </>
                  ) : null}
                  to the Topographies newsletter for musings from the cave,
                  events, exhibitions, and other TERRAIN Projects.
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default ContactPage;
